function draw(canvas) {
  if (!_image) return;
  const ctx = canvas.getContext('2d');
  canvas.width  = _image.naturalWidth;
  canvas.height = _image.naturalHeight;
  ctx.filter = filterString();
  ctx.drawImage(_image, 0, 0);
  ctx.filter = 'none';
}

